<!doctype html><html lang="id"><head><meta charset="utf-8"><title>Label {{ $product->name }}</title><style>*{box-sizing:border-box}body{margin:0;background:#e2e8f0;font-family:Arial,sans-serif}.toolbar{padding:14px;text-align:center}.toolbar button{border:0;border-radius:8px;background:#059669;color:#fff;padding:10px 18px;font-weight:700;cursor:pointer}.label{width:70mm;min-height:42mm;margin:10mm auto;padding:5mm;border:1px dashed #94a3b8;background:#fff;text-align:center}.name{font-weight:800;font-size:14px}.price{margin-top:4px;font-weight:900;font-size:18px}.bars{height:28mm;margin:4mm 0 2mm;background:repeating-linear-gradient(90deg,#000 0 1px,#fff 1px 3px,#000 3px 5px,#fff 5px 7px,#000 7px 8px,#fff 8px 11px)}.code{font:11px monospace;letter-spacing:3px}@media print{.toolbar{display:none}body{background:#fff}.label{margin:0;border:0;page-break-after:always}}</style></head><body><div class="toolbar"><button onclick="window.print()">Cetak Label</button></div><div class="label"><div class="name">{{ $product->name }}</div><div class="price">Rp {{ number_format($product->price, 0, ',', '.') }}</div><div class="bars"></div><div class="code">{{ $product->barcode ?: $product->code }}</div></div></body></html>
